function smartFreeBlock(model){
 if(model.current.id!=='libre')return model;
 const next=model.next,limit=next&&next.dayOffset!==1?next.start:Math.min(1440,model.minute+90);
 const available=Math.max(0,limit-model.minute);
 const a=data.smartActivity,valid=a&&a.day===kyivDay()&&Number.isFinite(a.startedAt)&&Number.isFinite(a.minutes)&&Date.now()<a.startedAt+a.minutes*60000&&available>0;const names={seguimientos:'Seguimientos',ventas:'Entrenar ventas',klimb:'KLIMB · producción',ingles:'Inglés',descanso:'Descanso'};model.current={...model.current,name:valid?(names[a.id]||'Actividad en curso'):'Pausa',kind:'free-choice',start:model.minute,end:limit,duration:available};
 model.freeGapEnd=limit;return model;
}
function markRestCompletedSilently(){const model=dashboardCommand();const limit=model.freeGapEnd||model.current.end;writeStore('sebasSmartGapV2:'+kyivDay()+':'+limit,{start:Date.now()-20*60000,restDone:true})}
function markRestCompleted(){const model=dashboardCommand();const limit=model.freeGapEnd||model.current.end;writeStore('sebasSmartGapV2:'+kyivDay()+':'+limit,{start:Date.now()-20*60000,restDone:true});view('hoy',true)}
function smartGapOptions(){
 const model=dashboardCommand(),available=model.current.kind==='free-choice'?Math.max(0,Math.floor((model.freeGapEnd||model.current.end)-model.minute)):0;
 return [{id:'seguimientos',label:'Seguimientos',done:false},{id:'ventas',label:'Entrenar ventas'},{id:'klimb',label:'KLIMB · producir vídeos'},{id:'ingles',label:'Inglés'},{id:'descanso',label:'Descanso'}].map(x=>({...x,available}));
}
function openSmartActivity(){
 document.getElementById('smart-activity-overlay')?.remove();
 const model=dashboardCommand(),available=Math.max(0,Math.floor((model.freeGapEnd||model.current.end)-model.minute));
 if(model.current.kind!=='free-choice'||available<1)return;
 const overlay=document.createElement('div');overlay.id='smart-activity-overlay';overlay.className='smart-activity-overlay';
 overlay.innerHTML='<section class="smart-activity-sheet" role="dialog" aria-modal="true" aria-label="Hacer ahora"><h2>¿Qué quieres hacer ahora?</h2><p>'+available+' min disponibles antes del siguiente compromiso.</p><div class="smart-activity-choices">'+smartGapOptions().map(x=>'<button '+(x.done?'disabled ':'')+'onclick="selectSmartActivity('+JSON.stringify(x.id).replace(/"/g,'&quot;')+')">'+esc(x.label)+(x.done?' · completado':'')+'</button>').join('')+'</div><button class="smart-activity-close" onclick="closeSmartActivity()">Cancelar</button></section>';
 overlay.addEventListener('click',e=>{if(e.target===overlay)closeSmartActivity()});
 document.body.appendChild(overlay);
}
function closeSmartActivity(){document.getElementById('smart-activity-overlay')?.remove()}
function selectSmartActivity(id){
 const choice=smartGapOptions().find(x=>x.id===id&&!x.done);if(!choice)return;
 const available=choice.available;
 const durations=[15,30,60].filter(n=>n<=available);
 const sheet=document.querySelector('#smart-activity-overlay .smart-activity-sheet');if(!sheet)return;
 sheet.innerHTML='<h2>'+esc(choice.label)+'</h2><p>¿Cuánto tiempo quieres dedicarle? Tienes '+available+' minutos libres.</p><div class="smart-activity-choices">'+durations.map(n=>'<button onclick="startSmartActivity('+JSON.stringify(id).replace(/"/g,'&quot;')+','+n+')">'+(n===60?'1 hora':n+' minutos')+'</button>').join('')+'</div><label class="smart-custom-duration">Otros minutos (máximo '+available+')<input id="smart-custom-minutes" type="number" min="1" max="'+available+'" step="1" inputmode="numeric" placeholder="Ej. 25"></label><button class="smart-activity-confirm" onclick="startSmartActivity('+JSON.stringify(id).replace(/"/g,'&quot;')+',Number(document.getElementById(\'smart-custom-minutes\').value))">Empezar</button><button class="smart-activity-close" onclick="openSmartActivity()">Volver</button>';
}
function startSmartActivity(id,minutes){
 const choice=smartGapOptions().find(x=>x.id===id&&!x.done);
 if(!choice||!Number.isInteger(minutes)||minutes<1||minutes>choice.available)return;
 data.smartActivity={id,minutes,startedAt:Date.now(),day:kyivDay()};save();closeSmartActivity();
 view('hoy',true);
}
function stopSmartActivity(){const a=data.smartActivity;if(a&&a.day===kyivDay()){const elapsed=Math.max(0,Math.min(a.minutes,Math.round((Date.now()-a.startedAt)/60000)));data.smartHistory=[...(data.smartHistory||[]).filter(x=>x.day===kyivDay()).slice(-49),{id:a.id,day:a.day,planned:a.minutes,actual:elapsed,endedAt:Date.now()}]}data.smartActivity=null;save();view('hoy',true)}
function chooseSmartActivity(id){openSmartActivity();if(id)selectSmartActivity(id)}

