function currentGymPhase(plan){
 if(trackData('gym').done)return {kind:'done',name:'Entrenamiento completado',left:0,index:0};
 const elapsed=workoutElapsed();if(plan.mode!=='gym')return SebasPlanner.phase(plan,elapsed);
 const session=data.gymSession?.day===kyivDay()?data.gymSession:null,index=Math.min(session?.exerciseIndex||0,plan.exercises.length-1);
 if(session?.strengthDone)return {kind:'cooldown',name:'Fuerza completada · baja el ritmo',left:Math.max(0,plan.total-elapsed),index};
 if(!session?.warmupDone&&elapsed<300)return {kind:'warmup',name:'Cardio suave · cinta o bicicleta',left:300-elapsed,index:0};
 const rest=session?.restFromSeconds,remaining=rest===null||rest===undefined?0:Math.max(0,(session?.restDuration||plan.restSeconds)-(elapsed-rest));
 return {kind:remaining?'rest':'work',name:remaining?'Recupera y respira':plan.exercises[index].name,left:remaining||Math.max(0,plan.total-elapsed),index};
}
function gymWarmupDone(){if(activeTrack?.id!=='gym'||!data.gymSession)return;data.gymSession.warmupDone=true;save();view('gym')}
function gymTarget(exercise){return Number(exercise.reps.match(/\d+/g)?.slice(-1)[0])||12}
function countGymRep(delta){const plan=trainingPlan(),session=data.gymSession;if(plan.mode!=='gym'||!session||activeTrack?.id!=='gym'||currentGymPhase(plan).kind!=='work')return;const e=plan.exercises[session.exerciseIndex||0];if(/\b(s|min)\b/.test(e.reps))return;session.repCount=Math.max(0,Math.min(100,(session.repCount||0)+delta));save();view('gym')}
function markGymSet(){const plan=trainingPlan(),session=data.gymSession;if(plan.mode!=='gym'||!session||activeTrack?.id!=='gym'||currentGymPhase(plan).kind!=='work')return;const index=Math.min(session.exerciseIndex||0,plan.exercises.length-1),exercise=plan.exercises[index];session.completedSets??={};const old=session.completedSets[exercise.id]||0;if(old>=plan.sets)return;session.completedSets[exercise.id]=old+1;session.repLog??=[];session.repLog.push({exerciseId:exercise.id,set:old+1,countedReps:session.repCount||null});session.repCount=0;session.pendingExerciseIndex=old+1>=plan.sets?index+1:index;session.restFromSeconds=workoutElapsed();session.restDuration=plan.restSeconds;save();view('gym')}
function advanceGymAfterRest(){const session=data.gymSession,plan=trainingPlan();if(!session||plan.mode!=='gym')return;session.restFromSeconds=null;session.restDuration=null;if(Number.isInteger(session.pendingExerciseIndex)){if(session.pendingExerciseIndex>=plan.exercises.length)session.strengthDone=true;else session.exerciseIndex=session.pendingExerciseIndex;session.pendingExerciseIndex=null;}session.repCount=0;save()}
function moveGymExercise(delta){const plan=trainingPlan();if(plan.mode!=='gym'||!data.gymSession)return;advanceGymAfterRest();data.gymSession.strengthDone=false;data.gymSession.exerciseIndex=Math.max(0,Math.min(plan.exercises.length-1,(data.gymSession.exerciseIndex||0)+delta));data.gymSession.repCount=0;save();view('gym')}
function skipGymRest(){if(!data.gymSession||activeTrack?.id!=='gym')return;advanceGymAfterRest();view('gym')}
function extendGymRest(){if(!data.gymSession||activeTrack?.id!=='gym')return;data.gymSession.restDuration=(data.gymSession.restDuration||75)+30;save();view('gym')}
function toggleRoutineChooser(){if(activeTrack?.id==='gym')return;routineChooserOpen=!routineChooserOpen;view('gym')}
function gymMission(plan,phase){
 const running=activeTrack?.id==='gym',session=data.gymSession?.day===kyivDay()?data.gymSession:null,done=trackData('gym').done;
 const e=plan.exercises[phase.index]||plan.exercises[0],completed=session?.completedSets?.[e.id]||0,repCount=session?.repCount||0,target=gymTarget(e),timed=/\b(s|min)\b/.test(e.reps),nextIndex=Number.isInteger(session?.pendingExerciseIndex)?session.pendingExerciseIndex:phase.index+1,next=plan.exercises[nextIndex];
 const total=plan.exercises.length*plan.sets,setsDone=Object.values(session?.completedSets||{}).reduce((a,n)=>a+n,0),label={warmup:'01 · ACTIVA EL CUERPO',work:'02 · TU SERIE',rest:'DESCANSO ENTRE SERIES',cooldown:'03 · VUELTA A LA CALMA',done:'SESIÓN COMPLETADA'}[phase.kind];
 const clock=phase.kind==='warmup'||phase.kind==='rest'?phase.left:Math.max(0,plan.total-workoutElapsed());
 return `<section class="gym-cockpit" data-gym-signature="${phase.kind}:${phase.index}:${completed}"><div class="gym-mission-top"><span class="eyebrow">CENTRO DE ENTRENAMIENTO</span><span class="gym-hour">60 MIN</span></div><div class="gym-mission-meta"><span>${esc(plan.name)}</span><strong><span data-gym-total>${formatTime(Math.max(0,plan.total-workoutElapsed()))}</span> <small>restantes</small></strong></div><div class="gym-mission-progress"><span style="width:${Math.min(100,setsDone/total*100)}%"></span></div><div class="gym-progress-copy">${setsDone} / ${total} series completadas <span>Ejercicio ${phase.index+1} / ${plan.exercises.length}</span></div><div class="gym-phase-label">${label}</div><h2 data-gym-phase>${esc(phase.name)}</h2>
 ${phase.kind==='warmup'?`<div class="gym-stage-clock" data-gym-countdown>${formatTime(clock)}</div><p class="gym-coach">Cinta o bicicleta a ritmo de conversación. Después, 1–2 series muy ligeras del primer ejercicio para preparar la técnica.</p><div class="gym-coming"><small>DESPUÉS DEL CARDIO</small><strong>${esc(plan.exercises[0].name)}</strong><span>${plan.sets} series · ${esc(plan.exercises[0].reps)} repeticiones</span></div>`:
 phase.kind==='rest'?`<div class="gym-stage-clock" data-gym-countdown>${formatTime(clock)}</div><p class="gym-coach">Relaja el agarre. Recupera la respiración. El siguiente paso aparece cuando termina el descanso.</p><div class="gym-coming"><small>SIGUIENTE</small><strong>${next?esc(next.name):'Vuelta a la calma'}</strong><span>${next?plan.sets+' series · '+esc(next.reps):'Baja el ritmo y termina cuando estés listo.'}</span></div><div class="gym-rest-actions"><button onclick="extendGymRest()" ${running?'':'disabled'}>+30 s descanso</button><button onclick="skipGymRest()" ${running?'':'disabled'}>Estoy listo →</button></div>`:
 phase.kind==='work'?`${gymExercisePhotos(e)}<div class="gym-target-grid"><div><small>SERIE</small><strong>${Math.min(completed+1,plan.sets)}<em> / ${plan.sets}</em></strong></div><div><small>${timed?'SEGUNDOS':'REPETICIONES OBJETIVO'}</small><strong>${esc(e.reps)}</strong></div></div><p class="gym-coach">${esc(e.hint)}</p><div class="gym-set-dots" aria-label="${completed} de ${plan.sets} series registradas">${Array.from({length:plan.sets},(_,i)=>`<span class="${i<completed?'complete':''}">${i<completed?'✓':i+1}</span>`).join('')}</div>${!timed?`<div class="gym-rep-counter"><p>Contador manual · ${repCount} repeticiones contadas</p><p><strong>${Math.max(0,target-repCount)}</strong> para llegar a ${target}</p><div><button aria-label="Restar repetición" onclick="countGymRep(-1)" ${running?'':'disabled'}>−</button><button aria-label="Contar repetición" onclick="countGymRep(1)" ${running?'':'disabled'}>+1 repetición</button></div></div>`:''}<button class="gym-primary" data-mark-set onclick="markGymSet()" ${!running||completed>=plan.sets?'disabled':''}>${completed>=plan.sets?'Series registradas':'Serie completada → descansar'}</button><small class="gym-honesty">Las series se guardan cuando las confirmas. El contador de repeticiones es manual.</small><div class="gym-coming"><small>DESPUÉS</small><strong>${next?esc(next.name):'Vuelta a la calma'}</strong></div>`:
 `<div class="gym-stage-clock" data-gym-countdown>${phase.kind==='done'?'✓':formatTime(clock)}</div><p class="gym-coach">${phase.kind==='done'?'Entrenamiento registrado. Recupera y prepara tu siguiente día.':'Has completado las series. Camina suave y recupera. El tiempo es una reserva, no una obligación de seguir si aparece fatiga o dolor.'}</p>`}
 <div class="gym-session-actions"><button class="${running?'gym-pause':'gym-primary'}" onclick="${running?'pauseTrack()':'startWorkout()'}">${done?'Iniciar otra sesión de 60 min':running?'Ⅱ Pausar':session?'Continuar sesión':'▶ Iniciar sesión · 60 min'}</button>${session&&!done?'<button class="gym-finish" onclick="finishTrack(\'gym\')">Terminar sesión</button>':''}${phase.kind==='warmup'&&running?'<button class="gym-finish" data-warmup-done onclick="gymWarmupDone()">Cardio y preparación listos →</button>':''}</div>${phase.kind==='work'?`<details class="gym-manual-nav"><summary>Elegir otro ejercicio</summary><div class="exercise-nav"><button onclick="moveGymExercise(-1)" ${!session||phase.index===0?'disabled':''}>← Anterior</button><button onclick="moveGymExercise(1)" ${!session||phase.index===plan.exercises.length-1?'disabled':''}>Siguiente →</button></div><small>Cambiar de ejercicio no completa sus series.</small></details>`:''}</section>`;
}
function gymDashboard(){
 const plan=trainingPlan(),phase=currentGymPhase(plan),place=trainingPlace(),running=activeTrack?.id==='gym';
 const menu=routineChooserOpen&&place==='gym'?`<div class="gym-routine-grid">${Object.entries(SebasPlanner.GYM_GROUPS).map(([id,g])=>`<button onclick="chooseGymRoutine('${id}')" ${running?'disabled':''}>${esc(g.name)}</button>`).join('')}</div>`:'';
 const home=place==='home';
 return `<section class="gym-page-heading"><div><span class="eyebrow">${home?'ALTERNATIVA · EN CASA':'TU GIMNASIO · PRIMERA OPCIÓN'}</span><h2>${home?'Entrenamiento en casa':esc(plan.name)}</h2><p>Sesiones de 60 minutos · cardio primero · fuerza después</p></div>${!home?`<button class="lightbtn" aria-expanded="${routineChooserOpen}" onclick="toggleRoutineChooser()" ${running?'disabled':''}>Cambiar rutina</button>`:''}</section>${menu}
 ${!home?gymMission(plan,phase):`<section class="activity-timer"><span class="eyebrow">CIRCUITO EN CASA · 60 MIN</span><h2 data-gym-phase>${esc(phase.name)}</h2><div class="countdown" data-gym-countdown>${formatTime(phase.left)}</div><p>5 min de cardio suave + 50 min de circuito + 5 min para bajar el ritmo.</p><div class="actions"><button onclick="${running?'pauseTrack()':'startWorkout()'}">${running?'Pausar':'Iniciar circuito · 60 min'}</button><button onclick="chooseTrainingPlace('gym')" ${running?'disabled':''}>Volver al gimnasio</button></div><h3>Entrena con Jaeho</h3><div id="video-slot">${videoPlayer(chosenVideo)}</div><p class="muted">El vídeo es una guía opcional; el circuito completo de la app dura 60 minutos.</p></section>`}
 <details class="card gym-full-plan"><summary>Ver toda la rutina · ${plan.exercises.length} ejercicios</summary>${plan.exercises.map((e,i)=>`<article class="exercise-row" data-exercise="${i}"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3>${!home?gymExercisePhotos(e):''}<p>${esc(e.hint)}</p><small>${!home?plan.sets+' series · '+esc(e.reps)+' · descanso 75–120 s':plan.rounds+' rondas · 40 s / 20 s'}</small></div></article>`).join('')}<p class="muted">Carga controlable; deja 2–3 repeticiones en reserva. Interrumpe si aparece dolor.</p></details>
 ${!home?gymWeekPlan():''}<details class="card gym-secondary"><summary>${home?'Volver a gimnasio':'Alternativa secundaria · entrenar en casa'}</summary><p>El gimnasio es tu opción principal. La alternativa de casa se aplica solo al día de hoy.</p><button class="lightbtn" onclick="chooseTrainingPlace('${home?'gym':'home'}')" ${running?'disabled':''}>${home?'Usar gimnasio':'Usar rutina en casa · 60 min'}</button></details>`;
}
function updateGymUI(){
 const plan=trainingPlan(),session=data.gymSession;
 if(plan.mode==='gym'&&session&&activeTrack?.id==='gym'&&session.restFromSeconds!==null&&session.restFromSeconds!==undefined&&workoutElapsed()-session.restFromSeconds>=(session.restDuration||plan.restSeconds))advanceGymAfterRest();
 const phase=currentGymPhase(plan),completed=session?.completedSets?.[plan.exercises[phase.index]?.id]||0,signature=phase.kind+':'+phase.index+':'+completed,frame=document.querySelector('[data-gym-signature]');
 if(frame&&frame.getAttribute('data-gym-signature')!==signature){view('gym',true);document.querySelector('.gym-cockpit')?.scrollIntoView?.({block:'start',behavior:'smooth'});return;}
 const title=document.querySelector('[data-gym-phase]'),clock=document.querySelector('[data-gym-countdown]'),total=document.querySelector('[data-gym-total]');
 if(title)title.textContent=phase.name;if(clock)clock.textContent=phase.kind==='done'?'✓':formatTime(phase.left);if(total)total.textContent=formatTime(Math.max(0,plan.total-workoutElapsed()));
}

function leadCard(event){return allLeadCards().find(x=>x.eventKey===SebasCore.eventKey(event))}
function eventResearch(event){const card=leadCard(event),confirmed=card?.confirmed===true&&card.eventUpdated===event.updated&&card.sessionStart===event.start,key=SebasCore.eventKey(event),ig=safeLink(card?.instagram,'instagram'),session=SebasOps.session(event,card);return `<article class="call-preview ${confirmed?'':'call-pending'}"><div class="call-time"><strong>${SebasPlanner.time(SebasPlanner.minute(Date.parse(event.start)))}</strong><span>${SebasPlanner.time(SebasPlanner.minute(Date.parse(event.end)))}</span></div><div class="call-preview-body"><span class="call-state">${confirmed?'CONFIRMADA':'POR CONFIRMAR'} · ${Math.round((Date.parse(event.end)-Date.parse(event.start))/60000)} MIN</span><h2>${esc(session.name)}</h2><p>${esc(session.label)}</p><div class="call-preview-actions"><button onclick="openCallReport(${jsArg(key)})">Ver informe</button>${ig?`<a href="${esc(ig)}" target="_blank" rel="noopener">Instagram ↗</a>`:''}</div></div></article>`}
function impulsoDashboard(){const focused=effectiveEvents().find(e=>SebasCore.eventKey(e)===focusedEventKey);if(focused&&!SebasLife.isCommercial(focused))return `<section class="card"><span class="eyebrow">EVENTO PERSONAL</span><h2>${esc(focused.name)}</h2><p>${esc(new Intl.DateTimeFormat('es',{timeZone:'Europe/Kyiv',dateStyle:'full',timeStyle:'short'}).format(new Date(focused.start)))}</p><button onclick="view('calendario')">Volver al calendario</button></section>`;const calls=effectiveEvents().filter(e=>!e.allDay&&(SebasCore.onDay(e)||SebasCore.eventKey(e)===focusedEventKey)&&SebasLife.isCommercial(e)),confirmed=SebasLife.scheduledEvents(calls,allLeadCards()),keys=new Set(confirmed.map(SebasCore.eventKey)),pending=calls.filter(e=>!keys.has(SebasCore.eventKey(e))),next=confirmed.find(e=>Date.parse(e.end)>Date.now()),minutes=confirmed.reduce((n,e)=>n+(Date.parse(e.end)-Date.parse(e.start))/60000,0);return `<section class="destination-hero calls-hero"><div class="destination-top"><span class="eyebrow">CLOSING · TU DÍA COMERCIAL</span><span class="source-pill">${recapDevice?'RECAP':'AGENDA'}</span></div><h2>Una llamada.<br>Una oportunidad.</h2><div class="destination-metrics"><div><strong>${confirmed.length}</strong><span>llamadas confirmadas</span></div><div><strong>${Math.floor(minutes/60)}<small>h ${Math.round(minutes%60)}m</small></strong><span>en sesiones</span></div></div><div class="destination-bottom"><span>${next?'Siguiente · '+SebasPlanner.time(SebasPlanner.minute(Date.parse(next.start))):'Tu agenda, a un vistazo'}</span><button class="hero-mini-action" onclick="openSaleDialog()">+ Añadir venta</button></div></section><div class="sectiontop calls-list-heading"><h2>Mis llamadas de hoy</h2>${recapDevice?recapUpdateControls():researchApiKey?'<button class="tinybutton" onclick="syncResearch(true)">Actualizar</button>':''}</div><p class="sync-caption" role="status">${esc(recapDevice?recapState.status:researchState.status)}</p>${recapState.error?'<p class="sync-error" role="alert">'+esc(recapState.error)+'</p>':''}${confirmed.length?confirmed.map(eventResearch).join(''):`<section class="card empty-state"><span class="empty-symbol" aria-hidden="true">◴</span><h3>${recapDevice?'A la espera del recap':'Tu próxima llamada empieza aquí'}</h3><p>${recapDevice?'Cuando llegue tu agenda, tendrás cada sesión con su informe.':'Conecta tu agenda privada para ver las llamadas y sus informes.'}</p>${!recapDevice?'<button onclick="view(\'ajustes\')">Conectar agenda</button>':''}</section>`}${pending.length?`<details class="card" ${sectionAttrs('pending-calls')}><summary>${pending.length} reserva${pending.length===1?'':'s'} por confirmar</summary>${pending.map(eventResearch).join('')}</details>`:''}`}
function readLead(key){const card=allLeadCards().find(x=>x.eventKey===key);if(!card?.summary)return;if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){const status=document.getElementById('voice-status');if(status)status.textContent='La lectura en voz alta no está disponible en este navegador.';return}stopReading();const run=speechRun,words=String(card.summary).split(/\s+/),chunks=[];let chunk='';for(const word of words){if(chunk.length+word.length>220&&chunk){chunks.push(chunk);chunk=''}chunk+=(chunk?' ':'')+word}if(chunk)chunks.push(chunk);let index=0;const speak=()=>{if(run!==speechRun||index>=chunks.length)return;const utterance=new window.SpeechSynthesisUtterance(chunks[index++]);utterance.lang='es-ES';utterance.rate=1;utterance.onend=speak;window.speechSynthesis.speak(utterance)};speak()}
function stopReading(){speechRun++;window.speechSynthesis?.cancel()}

let slackConnection={configured:false,connected:false,message:'Pendiente de activar el servicio de Slack'},slackAuthWindow=null,slackPoll=null;
function slackSettings(){return `<section class="card slack-connection"><span class="eyebrow">CONEXIÓN DIRECTA</span><h2>Slack</h2><p role="status" id="slack-state">${esc(slackConnection.message)}</p>${slackConnection.connected?`<p class="muted">${esc(slackConnection.team||'Slack')} · solo lectura</p><label>Canal de investigación<input id="slack-channel" placeholder="avisos-comerciales" value="${esc(slackConnection.channel||'')}" maxlength="80"></label><div class="actions"><button onclick="saveSlackChannel()">Guardar canal</button><button class="lightbtn" onclick="disconnectSlack()">Desconectar Slack</button></div>`:`<button onclick="connectSlack()" ${!researchApiKey||!slackConnection.configured?'disabled':''}>Conectar con Slack ↗</button>`}<p id="slack-message" role="status"></p>${!slackConnection.configured?'<p class="muted">La autorización estará disponible al activar Slack en el servicio privado.</p>':''}</section>`}
async function refreshSlackConnection(){if(!researchApiKey)return;try{slackConnection=await privateApi('/api/slack/status')}catch{slackConnection={configured:false,connected:false,message:'No se pudo verificar Slack. Revisa la conexión al servicio.'}}if(activeTab==='ajustes')view('ajustes',true)}
async function connectSlack(){if(!researchApiKey||!slackConnection.configured)return;slackAuthWindow=window.open('about:blank','sebas-slack-oauth','width=640,height=760');if(!slackAuthWindow){document.getElementById('slack-message').textContent='Permite la ventana de autorización y vuelve a intentarlo.';return}try{const result=await privateApi('/api/slack/start',{method:'POST',body:'{}'}),url=new URL(result.url);if(url.origin!=='https://slack.com'||url.pathname!=='/oauth/v2/authorize')throw Error('Enlace de autorización no válido.');slackAuthWindow.location=url.href;clearInterval(slackPoll);const stop=Date.now()+300000;slackPoll=setInterval(()=>{if(slackAuthWindow?.closed||Date.now()>stop){clearInterval(slackPoll);refreshSlackConnection()}},1500)}catch(e){slackAuthWindow.close();document.getElementById('slack-message').textContent=e.message}}
if(typeof window.addEventListener==='function')window.addEventListener('message',event=>{if(!data.researchUrl||event.origin!==new URL(data.researchUrl).origin||event.source!==slackAuthWindow||event.data?.type!=='sebas-slack-result')return;clearInterval(slackPoll);refreshSlackConnection()});
async function saveSlackChannel(){const channel=document.getElementById('slack-channel').value;try{await privateApi('/api/slack/channel',{method:'POST',body:JSON.stringify({channel})});await refreshSlackConnection()}catch(e){document.getElementById('slack-message').textContent=e.message}}
async function disconnectSlack(){try{await privateApi('/api/slack/disconnect',{method:'POST',body:'{}'});researchState.cards=[];await refreshSlackConnection()}catch(e){document.getElementById('slack-message').textContent=e.message}}
function researchSettings(){return `<section class="card"><h2>Investigación de llamadas</h2><p role="status">${esc(researchState.status)}</p><p class="muted">Conecta tu servidor privado de SEBAS OS. La conexión de Slack de ChatGPT no se transfiere a esta app. No pegues aquí tokens de Slack ni secretos de Google.</p><label>URL del servicio privado<input id="research-url" type="url" placeholder="https://tu-servidor.example" value="${esc(data.researchUrl||'')}"></label><p><label>Clave de acceso del servicio<input id="research-key" type="password" autocomplete="off" placeholder="Solo se conserva mientras la app está abierta"></label></p><div class="actions"><button onclick="connectResearch()">Conectar servicio</button><button class="lightbtn" onclick="disconnectResearch()">Desconectar</button><button onclick="enablePush()" ${researchState.connected?'':'disabled'}>Activar notificaciones</button></div><p id="research-message" role="status"></p><p class="muted">Sin un servidor configurado, no hay sincronización de Slack ni notificaciones con la app cerrada. Google en esta app sigue funcionando por separado.</p></section>`}
function routineSettings(){return bedtimeSettings()+'<section class="card"><h2>Planificación semanal</h2><p>Despertar y prepararte 20 min → oración → entrenamiento → lectura → desayuno → ducha y preparación.</p><p>Inglés: una hora sábado y domingo a las 09:00, y una mañana entre semana de 08:30 a 09:30. Propuestas según tus huecos; no son reservas de clases.</p><label>Mañana de inglés<select onchange="data.englishWeekday=Number(this.value);save();view(\'ajustes\',true)">'+[1,2,3,4,5].map((d,i)=>'<option value="'+d+'" '+((data.englishWeekday??5)===d?'selected':'')+'>'+['Lunes','Martes','Miércoles','Jueves','Viernes'][i]+'</option>').join('')+'</select></label><p>Daily 10:00. Preparación 09:40. Inglés termina 30 min antes del daily. Martes y viernes: Closing hasta las 18:30; después KLIMB. Mentoría de ventas: martes 20:00–21:00. Práctica comercial: sábado 15:00–16:00.</p><p class="muted">Los eventos reales sustituyen los bloques propuestos que coincidan.</p></section>'}
function saveRoutineHours(){}
async function privateApi(path,options={}){if(!data.researchUrl||!researchApiKey)throw Error('Conecta tu servicio privado en Ajustes.');const response=await fetch(data.researchUrl+path,{...options,headers:{Authorization:'Bearer '+researchApiKey,'Content-Type':'application/json',...(options.headers||{})},cache:'no-store',signal:AbortSignal.timeout(25000)});if(!response.ok)throw Error(response.status===401?'La clave de acceso no es válida.':'El servicio no pudo completar la consulta ('+response.status+').');return response.json()}
async function connectResearch(){const input=document.getElementById('research-url').value.trim().replace(/\/$/,'');try{const url=new URL(input);if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1','terminal.local'].includes(url.hostname)))throw Error();if(url.username||url.password||url.search||url.hash||url.pathname!=='/')throw Error();}catch{document.getElementById('research-message').textContent='Usa la URL HTTPS de tu servicio privado, sin rutas ni parámetros.';return}researchApiKey=document.getElementById('research-key').value;data.researchUrl=input;save();await syncResearch(true);await refreshSlackConnection()}
async function syncResearch(force=false){if(researchBusy)return;if(!researchApiKey){researchState.status='Servicio privado sin conectar';if(force)view('ajustes');return}researchBusy=true;researchState.status='Sincronizando investigación…';try{if(force)await privateApi('/api/sync',{method:'POST',body:'{}'});const result=await privateApi('/api/today');researchState={connected:true,status:result.status||'Conectado al servicio privado',events:Array.isArray(result.events)?result.events:[],cards:Array.isArray(result.cards)?result.cards:[],lastSync:result.lastSync||Date.now()};notifySameDay(researchState.events);}catch(e){researchState.connected=false;researchState.status=e.message+' Se conserva la última consulta.';}finally{researchBusy=false;if(['hoy','impulso','ajustes'].includes(activeTab))view(activeTab)}}
async function disconnectResearch(){if(navigator.serviceWorker){try{const registration=await navigator.serviceWorker.getRegistration();const subscription=await registration?.pushManager?.getSubscription();if(subscription){if(researchApiKey)await privateApi('/api/push/subscriptions',{method:'DELETE',body:JSON.stringify({endpoint:subscription.endpoint})});await subscription.unsubscribe()}}catch{calendarNotice='La conexión local se ha cerrado; no se pudo confirmar la baja de notificaciones en el servidor.'}}researchApiKey='';slackConnection={configured:false,connected:false,message:'Servicio privado sin conectar'};researchState={connected:false,status:'Sin conectar',events:[],cards:[],lastSync:null};noticeBaseline=null;stopReading();view('ajustes')}
function notifySameDay(events){const now=Date.now(),m=SebasPlanner.minute(now);const keys=new Set(events.filter(e=>SebasCore.onDay(e)&&Date.parse(e.start)>now).map(SebasCore.eventKey));if(noticeBaseline&&m>=360&&m<1260){const added=events.filter(e=>keys.has(SebasCore.eventKey(e))&&!noticeBaseline.has(SebasCore.eventKey(e)));if(added.length)calendarNotice='Te han puesto '+added.length+' sesión nueva hoy. Abre Impulso para ver su investigación.';}noticeBaseline=keys}
async function enablePush(){try{if(!('PushManager'in window)||!('Notification'in window))throw Error('Este navegador no ofrece notificaciones push. En iPhone, abre la PWA instalada desde la pantalla de inicio.');const config=await privateApi('/api/push/key');if(!config.publicKey)throw Error('El servidor todavía no tiene configuradas las notificaciones push.');const permission=await window.Notification.requestPermission();if(permission!=='granted')throw Error('No se concedió permiso para notificaciones.');const registration=await navigator.serviceWorker.ready;const pad='='.repeat((4-config.publicKey.length%4)%4),bytes=atob((config.publicKey+pad).replace(/-/g,'+').replace(/_/g,'/'));const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(bytes,c=>c.charCodeAt(0))});await privateApi('/api/push/subscriptions',{method:'POST',body:JSON.stringify(subscription.toJSON())});document.getElementById('research-message').textContent='Suscripción registrada. La entrega con la app cerrada depende del servidor y los permisos del dispositivo.';}catch(e){document.getElementById('research-message').textContent=e.message}}
function tickDashboard(){updateTransitionUI();document.querySelectorAll('[data-command-until]').forEach(el=>el.textContent=formatTime(Math.max(0,Number(el.dataset.commandUntil)*60-SebasPlanner.minute()*60-new Date().getUTCSeconds())));const m=SebasPlanner.minute();document.querySelectorAll('[data-kyiv-clock]').forEach(e=>e.textContent=SebasPlanner.time(m));document.querySelectorAll('[data-countdown]').forEach(e=>e.textContent=formatTime(Math.max(0,Number(e.dataset.target)-currentSeconds(e.dataset.countdown))));document.querySelectorAll('[data-timer-progress]').forEach(e=>e.style.width=Math.min(100,currentSeconds(e.dataset.timerProgress)/Number(e.dataset.target)*100)+'%');if(activeTab==='gym')updateGymUI();if(m!==lastDashboardMinute&&activeTab==='hoy'&&!pendingCompletion&&!openedFoodId){lastDashboardMinute=m;view('hoy')}}

let commandScrollDay='',commandScrollPosition=null,commandAutoFollow=true;
function commandItems(model){const list=model.items.filter(x=>x.id!=='trabajo'||model.current.id==='trabajo');const current=model.current;const idx=list.findIndex(x=>x.id===current.id&&(x.start===current.start||(current.kind==='active'&&x.start<=model.minute&&x.end>model.minute)));if(idx>=0)list[idx]={...list[idx],...current,current:true};else list.push({...current,end:current.end||current.start+(current.duration||30),current:true});return list.sort((a,b)=>a.start-b.start)}
function activityBackground(item){const scene={despertar:'dawn',oracion:'prayer',gym:'training',lectura:'reading',ducha:'prepare',preparacion:'prepare',descanso:'rest',postcall:'rest',dormir:'rest'}[item.id]||'focus';return 'assets/scene-'+scene+'.webp'}
function commandDay(model){const items=commandItems(model);return `<section class="command-hero command-day" data-command-frame><div class="command-top"><span class="eyebrow">KPI · CENTRO DE MANDO</span><button class="command-now" onclick="jumpToNow()">Ahora <span data-kyiv-clock>${SebasPlanner.time(model.minute)}</span></button></div><div class="command-scroll" id="command-scroll" tabindex="0" role="region" aria-label="Agenda del día. Desliza hacia arriba o abajo" onscroll="commandScrollPosition=this.scrollTop" onwheel="commandAutoFollow=false" ontouchstart="commandAutoFollow=false" onkeydown="commandAutoFollow=false">${items.map((x,index)=>{const meal=mealForActivity(x.id),quiet=['descanso','postcall','despertar','dormir','ducha'].includes(x.id),title=x.kind==='event'&&SebasLife.isCommercial(x.event)?SebasOps.session(x.event,leadCard(x.event)).name:meal?meal.name:x.name;return `<article class="command-slide ${meal?'command-meal':''}" data-current="${!!x.current}" style="background-image:linear-gradient(90deg,#070c16dc,#070c1640),linear-gradient(0deg,#070c1680,transparent),url('${meal?mealImage(meal.type,meal):activityBackground(x)}')"><div class="now-label">${x.current?'AHORA':SebasPlanner.time(x.start)+(Number.isFinite(x.end)?'–'+SebasPlanner.time(x.end):'')}${meal?' · '+FOOD_LABELS[meal.type]:''}</div><h2>${esc(title)}</h2>${x.id==='klimb'?(data.klimbTasks||[]).filter(t=>t.id===data.klimbFocusTask&&!t.done).map(t=>'<p class="command-context">'+esc(t.title)+'</p>').join(''):''}${x.id==='desayuno'?'<small class="command-meal-timing">10 min preparar · 15 min desayunar</small>':''}${x.current?commandMainClock(x):''}${quiet?'':`<button class="command-cta" onclick="openCommandItem(${index})">${meal?'Ver receta':(x.id==='libre'||x.kind==='free-choice')?'Quiero hacer algo':'Ver actividad'}<span aria-hidden="true">↗</span></button>`}${x.id==='cena'?'<button class="quick-command" onclick="quickDinner()">Sin tiempo · cena rápida</button>':''}</article>`}).join('')}</div><footer class="command-footer">${transitionPanel()}</footer><div class="command-scroll-hint">↕ Recorre tu día</div></section>`}
function openCommandItem(index){const item=commandItems(dashboardCommand())[index];if(!item)return;if(item.event)openEvent(SebasCore.eventKey(item.event));else {const meal=mealForActivity(item.id);if(meal)openFood(meal.id);else if(item.id==='libre'||item.kind==='free-choice')openSmartActivity();else openActivity(item.id)}}
function restoreCommandScroll(){const el=document.getElementById('command-scroll');if(!el?.querySelector)return;if(commandScrollDay!==kyivDay()){commandScrollDay=kyivDay();commandScrollPosition=null;commandAutoFollow=true}const current=el.querySelector('[data-current="true"]');el.scrollTop=commandAutoFollow?(current?current.offsetTop:0):(commandScrollPosition??0)}
function jumpToNow(){commandAutoFollow=true;commandScrollPosition=null;restoreCommandScroll()}
let bedtimeAudio=null,bedtimeChimeTimer=null;
function bedtimeSettings(){return `<section class="card"><div class="sectiontop"><h2>Dormir</h2><span class="eventpill">23:30 · Kyiv</span></div><p class="muted">Aviso en pantalla con la app abierta. No suena con la app cerrada ni puede saltarse el silencio del iPhone.</p><button onclick="enableBedtimeSound()">Activar y probar sonido</button><p id="bedtime-sound-status" role="status"></p></section>`}
async function enableBedtimeSound(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Sonido no disponible en este navegador.');bedtimeAudio??=new Audio();await bedtimeAudio.resume();if(bedtimeAudio.state!=='running')throw Error('El navegador ha bloqueado el sonido.');data.bedtimeSound=true;save();playBedtimeChime();document.getElementById('bedtime-sound-status').textContent='Sonido activado en esta sesión, con la app abierta.'}catch(e){const status=document.getElementById('bedtime-sound-status');if(status)status.textContent=e.message}}
function playBedtimeChime(){if(!bedtimeAudio||bedtimeAudio.state!=='running')return;[523.25,659.25,783.99].forEach((frequency,i)=>{const oscillator=bedtimeAudio.createOscillator(),gain=bedtimeAudio.createGain(),start=bedtimeAudio.currentTime+i*.35;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.16,start+.03);gain.gain.exponentialRampToValueAtTime(.001,start+.8);oscillator.connect(gain);gain.connect(bedtimeAudio.destination);oscillator.start(start);oscillator.stop(start+.85)})}
function tickBedtime(){if(SebasPlanner.minute()<1410||document.visibilityState!=='visible'||data.bedtimeDismissed===kyivDay()||document.getElementById('bedtime-dialog')?.open)return;const d=document.createElement('dialog');if(!d.showModal)return;d.id='bedtime-dialog';d.className='sale-dialog bedtime-dialog';d.setAttribute('aria-labelledby','bedtime-title');d.innerHTML='<span class="eyebrow">23:30 · HORA DE DORMIR</span><div class="bedtime-moon">☾</div><h2 id="bedtime-title">Por hoy, ya está.</h2><p>Es momento de dormir, Sebastián.</p><button onclick="dismissBedtime()">Me voy a dormir</button>';d.addEventListener('cancel',e=>{e.preventDefault();dismissBedtime()});document.body.append(d);d.showModal();const chime=()=>{if(!d.isConnected)return;if(data.bedtimeSound)playBedtimeChime();bedtimeChimeTimer=setTimeout(chime,8000)};chime()}
function dismissBedtime(){clearTimeout(bedtimeChimeTimer);document.getElementById('bedtime-dialog')?.remove();data.bedtimeDismissed=kyivDay();save()}

function scheduleTransition(now=Date.now()){return SebasOps.transition(SebasLife.scheduledEvents(effectiveEvents(),allLeadCards()),activeTrack,now,plannerOptions())}
function transitionCopy(t){if(t.state==='idle')return {label:'SIN MÁS CAMBIOS',detail:t.name};if(t.state==='overdue')return {label:'CAMBIO DE ACTIVIDAD',detail:'Ya toca · '+t.name};return {label:'SIGUIENTE · '+SebasPlanner.time(t.target.start),detail:t.name+' · '+formatTime(Math.max(0,t.seconds))}}
function transitionPanel(){const t=scheduleTransition(),c=transitionCopy(t);return `<div class="transition-cue" data-transition-state="${t.state}"><div><span data-transition-label>${esc(c.label)}</span><strong data-transition-detail>${esc(c.detail)}</strong></div><button aria-label="Ver siguiente actividad" class="transition-open" onclick="openTransition()" ${t.target?'':'hidden'}>↗</button><div class="transition-bar" role="progressbar" aria-label="Proximidad del cambio de actividad" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(t.ratio*100)}"><span style="width:${t.ratio*100}%"></span></div></div>`}
function activeTimerRail(){if(!activeTrack)return '';const track=TRACKS.find(t=>t.id===activeTrack.id);return `<div class="active-timer-rail"><span class="timer-dot"></span><div><small>CRONÓMETRO EN CURSO</small><strong>${esc(track?.name||activeTrack.id)}</strong></div><b data-track-seconds="${activeTrack.id}">${formatTime(currentSeconds(activeTrack.id))}</b><button class="rail-control" onclick="pauseTrack()" aria-label="Pausar cronómetro">Ⅱ</button><button class="rail-control" onclick="openActivity('${activeTrack.id}')" aria-label="Abrir cronómetro">↗</button></div>`}
function openTransition(){const t=scheduleTransition();if(!t.target)return;if(t.target.event)openEvent(SebasCore.eventKey(t.target.event));else {const meal=mealForActivity(t.target.id);if(meal)openFood(meal.id);else if(['descanso','postcall','despertar','dormir','ducha'].includes(t.target.id))jumpToNow();else openActivity(t.target.id)}}
function updateTransitionUI(){const t=scheduleTransition(),c=transitionCopy(t);document.querySelectorAll('[data-transition-state]').forEach(el=>{el.dataset.transitionState=t.state;const label=el.querySelector('[data-transition-label]'),detail=el.querySelector('[data-transition-detail]'),bar=el.querySelector('[role="progressbar"]');if(label)label.textContent=c.label;if(detail)detail.textContent=c.detail;if(bar){bar.setAttribute('aria-valuenow',Math.round(t.ratio*100));bar.firstElementChild.style.width=t.ratio*100+'%'}});document.querySelectorAll('[data-command-frame]').forEach(el=>el.dataset.urgency=t.state);document.querySelectorAll('[data-next-watermark]').forEach(el=>{el.hidden=!['amber','red','overdue'].includes(t.state);el.querySelector('[data-watermark-label]').textContent=t.state==='overdue'?'Ahora toca':'Siguiente';el.querySelector('[data-watermark-name]').textContent=t.name})}
function moreDashboard(){return `<section class="card"><span class="eyebrow">TU ESPACIO</span><h2>Más</h2><div class="more-grid">${[['calendario','Calendario','▦'],['comidas','Comidas','♧'],['gym','Entrenamiento','↗'],['lectura','Lectura','▤'],['habitos','Hábitos','✓'],['estadisticas','Estadísticas','◴'],['ajustes','Ajustes y conexiones','⚙']].map(([id,name,icon])=>`<button onclick="view('${id}')"><span>${icon}</span><strong>${name}</strong><small>Abrir ↗</small></button>`).join('')}</div></section>`}

function settingsDashboard(){return `<section class="card"><span class="eyebrow">A TU MEDIDA</span><h2>Ajustes</h2><div class="settings-status"><span class="status-dot ${googleToken?'connected':''}"></span><div><strong>Google Calendar</strong><small>${esc(googleStatus)}</small></div></div><div class="settings-status"><span class="status-dot ${recapDevice?'connected':''}"></span><div><strong>Agenda ChatGPT</strong><small>${esc(recapState.status)}</small></div></div><div class="settings-status"><span class="status-dot ${slackConnection.connected?'connected':''}"></span><div><strong>Slack</strong><small>${esc(slackConnection.message)}</small></div></div></section><details class="card" ${sectionAttrs('settings-connect')}><summary>Conexiones y notificaciones</summary>${recapSettings()+calendarSettings()}<details class="slack-service-advanced"><summary>Slack directo · conexión opcional</summary>${slackSettings()}</details><details class="slack-service-advanced"><summary>Configuración del servicio privado</summary>${researchSettings()}</details><p class="muted">ChatGPT: pendiente de conexión segura.</p></details><details class="card" ${sectionAttrs('settings-plan')}><summary>Planificación y hora de dormir</summary>${routineSettings()}</details><details class="card" ${sectionAttrs('settings-goals')}><summary>Modificar metas de actividades</summary>${goalSettings()}</details>`}

function nextWatermark(){const t=scheduleTransition(),visible=['amber','red','overdue'].includes(t.state);return `<div class="next-watermark" data-next-watermark ${visible?'':'hidden'}><span data-watermark-label>${t.state==='overdue'?'Ahora toca':'Siguiente'}</span><strong data-watermark-name>${esc(t.name)}</strong></div>`}

function commandMainClock(item){if(item.kind==='free-choice'){const a=data.smartActivity;if(a&&a.day===kyivDay()&&Date.now()<a.startedAt+a.minutes*60000)return '<div class="command-main-timer"><span>'+formatTime(Math.max(0,Math.min(Math.ceil((a.startedAt+a.minutes*60000-Date.now())/1000),Math.floor((item.end-SebasPlanner.minute())*60))))+'</span><small>Actividad elegida · '+esc(a.id)+' · '+a.minutes+' min</small><button onclick="stopSmartActivity()">Terminar · volver a pausa</button></div>';return '<div class="command-main-timer"><span>'+formatTime(Math.max(0,Math.floor((item.end-SebasPlanner.minute())*60)))+'</span><small>'+Math.max(0,Math.floor(item.end-SebasPlanner.minute()))+' minutos libres · hasta las '+SebasPlanner.time(item.end)+'</small></div>'}if(activeTrack){return `<div class="command-main-timer"><span data-track-seconds="${activeTrack.id}">${formatTime(currentSeconds(activeTrack.id))}</span><small>Cronómetro · ${esc(TRACKS.find(t=>t.id===activeTrack.id)?.name||'')}</small><div class="command-timer-controls"><button aria-label="Pausar cronómetro" onclick="pauseTrack()">Ⅱ</button><button onclick="finishTrack('${activeTrack.id}')">Terminar</button></div></div>`}const track=TRACKS.find(t=>t.id===item.id);if(track&&trackData(track.id).done)return '<div class="command-main-timer"><span>✓</span><small>Completado</small></div>';if(track)return `<div class="command-main-timer"><span>${formatTime(Math.max(0,(item.duration||track.goal)*60-currentSeconds(track.id)))}</span><button class="command-start" onclick="${track.id==='gym'?'startWorkout()':`beginTrack('${track.id}')`}">▶ Iniciar</button></div>`;if(Number.isFinite(item.end))return `<div class="command-main-timer"><span data-command-until="${item.end}">${formatTime(Math.max(0,item.end*60-SebasPlanner.minute()*60-new Date().getUTCSeconds()))}</span><small>Hasta las ${SebasPlanner.time(item.end)}</small></div>`;return ''}
